const { withDangerousMod } = require("@expo/config-plugins");
const fs = require("node:fs");
const path = require("node:path");

/**
 * Post-processes Android surfaces generated by with-binario-android-widget.
 *
 * The companion watch surface is intentionally non-standalone: realtime and
 * voice hand-off depend on the paired phone. This hardening pass also keeps
 * dynamically registered app-local receivers non-exported on every supported
 * Android release and relies on the Android Gradle Plugin's standard debug
 * signing for both phone and Wear instead of repository-local keystores.
 * Keeping these invariants in a config plugin makes Expo prebuild deterministic
 * instead of patching generated Android output by hand.
 */
module.exports = function withBinarioWearManifest(config) {
  return withDangerousMod(config, ["android", async (next) => {
    const platformRoot = next.modRequest.platformProjectRoot;
    const appBuildGradlePath = path.join(platformRoot, "app", "build.gradle");
    if (!fs.existsSync(appBuildGradlePath)) {
      throw new Error("Binario Companion build.gradle was not generated before signing hardening.");
    }

    let appBuildGradle = fs.readFileSync(appBuildGradlePath, "utf8");
    const appSigningComment = "    // Use AGP's standard debug signing; CI must not depend on a repository-local keystore.\n";
    const appSigningBlock = /\s*signingConfigs\s*\{\s*debug\s*\{\s*storeFile\s+file\(['\"]debug\.keystore['\"]\)\s*storePassword\s+['\"]android['\"]\s*keyAlias\s+['\"]androiddebugkey['\"]\s*keyPassword\s+['\"]android['\"]\s*\}\s*\}\s*/m;
    appBuildGradle = appBuildGradle.replace(appSigningBlock, `\n${appSigningComment}`);
    appBuildGradle = appBuildGradle.replace(/^\s*signingConfig\s+signingConfigs\.debug\s*$/gm, "");

    if (appBuildGradle.includes("file('debug.keystore')") || appBuildGradle.includes("signingConfig signingConfigs.debug")) {
      throw new Error("Binario Companion still depends on a repository-local debug keystore after hardening.");
    }
    fs.writeFileSync(appBuildGradlePath, appBuildGradle);

    const wearRoot = path.join(platformRoot, "wear");
    const manifestPath = path.join(wearRoot, "src", "main", "AndroidManifest.xml");

    if (!fs.existsSync(manifestPath)) {
      throw new Error("Binario Wear manifest was not generated before Wear hardening.");
    }

    let manifest = fs.readFileSync(manifestPath, "utf8");
    const standaloneName = "com.google.android.wearable.standalone";
    const metadata = `    <meta-data android:name="${standaloneName}" android:value="false" />`;

    if (manifest.includes(`android:name="${standaloneName}"`)) {
      manifest = manifest.replace(
        /\s*<meta-data\s+android:name="com\.google\.android\.wearable\.standalone"\s+android:value="(?:true|false)"\s*\/>/,
        `\n${metadata}`,
      );
    } else {
      const applicationTag = /(<application\b[^>]*>)/;
      if (!applicationTag.test(manifest)) {
        throw new Error("Binario Wear manifest has no application element to harden.");
      }
      manifest = manifest.replace(applicationTag, `$1\n${metadata}`);
    }
    fs.writeFileSync(manifestPath, manifest);

    const buildGradlePath = path.join(wearRoot, "build.gradle");
    if (!fs.existsSync(buildGradlePath)) {
      throw new Error("Binario Wear build.gradle was not generated before signing hardening.");
    }

    let buildGradle = fs.readFileSync(buildGradlePath, "utf8");
    const signingComment = "  // Use AGP's standard debug signing; CI must not depend on a repository-local keystore.\n";
    const wearSigningBlock = /\s*signingConfigs\s*\{\s*debug\s*\{\s*storeFile\s+rootProject\.file\(['\"]app\/debug\.keystore['\"]\)\s*storePassword\s+['\"]android['\"]\s*keyAlias\s+['\"]androiddebugkey['\"]\s*keyPassword\s+['\"]android['\"]\s*\}\s*\}\s*/m;
    buildGradle = buildGradle.replace(wearSigningBlock, `\n${signingComment}`);
    buildGradle = buildGradle.replace(/^\s*signingConfig\s+signingConfigs\.debug\s*$/gm, "");

    if (buildGradle.includes('rootProject.file("app/debug.keystore")') || buildGradle.includes("signingConfig signingConfigs.debug")) {
      throw new Error("Binario Wear still depends on a repository-local debug keystore after hardening.");
    }
    fs.writeFileSync(buildGradlePath, buildGradle);

    const voiceActivityPath = path.join(
      wearRoot,
      "src",
      "main",
      "java",
      "im",
      "binario",
      "companion",
      "wear",
      "BinarioVoiceRequestActivity.kt",
    );
    if (!fs.existsSync(voiceActivityPath)) {
      throw new Error("Binario Wear voice activity was not generated before receiver hardening.");
    }

    let voiceActivity = fs.readFileSync(voiceActivityPath, "utf8");
    voiceActivity = voiceActivity.replace("import android.os.Build\n", "");
    if (!voiceActivity.includes("import androidx.core.content.ContextCompat")) {
      voiceActivity = voiceActivity.replace(
        "import android.widget.TextView\n",
        "import android.widget.TextView\nimport androidx.core.content.ContextCompat\n",
      );
    }

    const legacyRegistration = '    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) registerReceiver(replyReceiver, filter, Context.RECEIVER_NOT_EXPORTED) else @Suppress("DEPRECATION") registerReceiver(replyReceiver, filter)';
    const hardenedRegistration = "    ContextCompat.registerReceiver(this, replyReceiver, filter, ContextCompat.RECEIVER_NOT_EXPORTED)";
    if (voiceActivity.includes(legacyRegistration)) {
      voiceActivity = voiceActivity.replace(legacyRegistration, hardenedRegistration);
    } else if (!voiceActivity.includes(hardenedRegistration)) {
      throw new Error("Binario Wear voice receiver registration no longer matches the expected generated source.");
    }

    fs.writeFileSync(voiceActivityPath, voiceActivity);
    return next;
  }]);
};
